    repair_job_store_path: ?[]const u8 = null,
    repair_job_retention_ms: ?u64 = null,
    restore_job_store_path: ?[]const u8 = null,
    restore_execution_guard: ?RestoreExecutionGuard = null,
    /// Local scratch root for remote backup upload staging. When omitted, the
    /// configured local storage root (or Lite file directory) is used.
    backup_staging_root: ?[]const u8 = null,
    session_ttl_ns: ?u64 = null,
    session_cleanup_interval_ns: ?u64 = null,
    session_owner_lease_ttl_ns: ?u64 = null,
    session_owner_lease_renew_interval_ns: ?u64 = null,
    session_savepoint_limit: ?usize = null,
    session_max_count: ?usize = null,
    session_max_record_bytes: ?usize = null,
    /// Optional node-wide resource owner. The owner must outlive ApiHttpServer.
    /// Cache budgets and concurrency are intentionally not HTTP/API config.
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
};

pub const trusted_principal_header = "X-Antfly-Trusted-Principal";

pub const AuthenticatedRequest = struct {
    authorization: ?[]const u8 = null,
    trusted_principal: ?[]const u8 = null,
};

pub const SemanticStatusResolver = struct {
    source: StatusSource,
    antfly_provider: ?managed_embedder.AntflyProvider = null,
    io: ?std.Io = null,
    remote_content: ?*const scraping.RemoteContentConfig = null,
    inference_api_url: ?[]const u8 = null,
    inference_api_key: ?[]const u8 = null,
    secret_store: ?*common_secrets.FileStore = null,
    query_embedding_cache: ?*query_embedding_cache.QueryEmbeddingCache = null,
    query_embedding_budget: ?*cache_budget.CacheBudget = null,
    query_embedding_security_domain: managed_embedder.QueryCacheSecurityDomain = .internal,
    query_embedding_security_scope: []const u8 = "internal",
    query_embedding_deadline_ns: ?u64 = null,

    pub fn iface(self: *SemanticStatusResolver) query_contract.SemanticResolver {
        return .{
            .ptr = self,
            .vtable = &.{
                .resolve_dense_query = resolveDenseQuery,
            },
        };
    }

    fn resolveDenseQuery(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
        semantic_search: []const u8,
        embedding_template: ?[]const u8,
        limit: u32,
    ) !db_mod.types.DenseKnnQuery {
        const self: *SemanticStatusResolver = @ptrCast(@alignCast(ptr));
        return try http_internal_group_read_routes.planSemanticQuery(.{
            .ptr = self.source.ptr,
            .admin_snapshot = self.source.vtable.admin_snapshot orelse return error.UnsupportedQueryRequest,
            .free_admin_snapshot = self.source.vtable.free_admin_snapshot orelse return error.UnsupportedQueryRequest,
            .antfly_provider = self.antfly_provider,
            .io = self.io,
            .remote_content = self.remote_content,
            .inference_api_url = self.inference_api_url,
            .inference_api_key = self.inference_api_key,
            .secret_store = self.secret_store,
            .query_embedding_cache = self.query_embedding_cache,
            .query_embedding_budget = self.query_embedding_budget,
            .query_embedding_security_domain = self.query_embedding_security_domain,
            .query_embedding_security_scope = self.query_embedding_security_scope,
            .query_embedding_deadline_ns = self.query_embedding_deadline_ns,
        }, alloc, table_name, index_name, semantic_search, embedding_template, limit);
    }
};

pub const TableVisibility = enum {
    present,
    absent,
};

pub const AuthenticatedIdentity = struct {
    username: []u8,
    permissions: []usermgr.Permission = &.{},
    row_filter: []usermgr.RowFilterEntry = &.{},
    metadata_json: []u8 = &.{},
    roles: [][]u8 = &.{},

    pub fn deinit(self: *AuthenticatedIdentity, alloc: std.mem.Allocator) void {
        alloc.free(self.username);
        for (self.permissions) |*permission| permission.deinit(alloc);
        if (self.permissions.len > 0) alloc.free(self.permissions);
        for (self.row_filter) |*entry| entry.deinit(alloc);
        if (self.row_filter.len > 0) alloc.free(self.row_filter);
        if (self.metadata_json.len > 0) alloc.free(self.metadata_json);
        for (self.roles) |role| alloc.free(role);
        if (self.roles.len > 0) alloc.free(self.roles);
        self.* = undefined;
    }
};

