    /// Build the GET /connections response body. Shared by the legacy
    /// dispatcher and the generated httpx handler so both paths use the same
    /// per-connection result cache. The caller owns the returned JSON.
    pub fn listConnectionsJsonAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        types_param: ?[]const u8,
        include_param: ?[]const u8,
        refresh_param: ?[]const u8,
    ) ![]u8 {
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();

        var snapshot_opt = self.source.cachedAdminSnapshot() catch null;
        if (snapshot_opt == null) snapshot_opt = self.source.adminSnapshot() catch null;
        defer if (snapshot_opt) |*snapshot| self.source.freeAdminSnapshot(snapshot);

        const node_config = self.cfg.node_config;
        const response = try connections_api.buildConnectionsResponse(arena, .{
            .node_config = node_config,
            .snapshot = if (snapshot_opt) |*snapshot| snapshot else null,
            .antfly_provider = self.antfly_provider,
            .inference_api_url = if (node_config) |cfg| cfg.inference.api_url else null,
            .inference_api_key = self.cfg.inference_api_key,
            .secret_store = self.cfg.secret_store,
            .io = if (self.cfg.backend_runtime) |runtime|
                if (runtime.apiIoImpl()) |io_impl| io_impl.io() else null
            else
                null,
        }, &self.connections_cache, .{
            .include_models = connections_api.includeHasModels(include_param),
            .probe = connections_api.includeHasStatus(include_param),
            .refresh = if (refresh_param) |value| std.mem.eql(u8, value, "true") else false,
            .types_filter = types_param,
        });
        return try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(response, .{})});
    }

    pub fn invokeInferenceConnection(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        connection_id: []const u8,
        operation: []const u8,
        body: []const u8,
    ) !connections_api.InvokeResult {
        const node_config = self.cfg.node_config orelse return error.ConnectionNotFound;
        var client = httpx.Client.initWithConfig(alloc, self.inferenceIo(), .{ .keep_alive = false });
        defer client.deinit();
        return connections_api.invokeInferenceConnection(
            alloc,
            &client,
            node_config,
            self.cfg.secret_store,
            connection_id,
            operation,
            body,
        );
    }

    /// Shared asynchronous I/O runtime for short-lived API helpers. Borrowers
    /// must not retain it beyond the server lifetime.
    pub fn sharedApiIo(self: *ApiHttpServer) ?std.Io {
        const runtime = self.cfg.backend_runtime orelse return null;
        const io_impl = runtime.apiIoImpl() orelse runtime.io_impl orelse return null;
        return io_impl.io();
    }

    pub fn joinContext(self: *ApiHttpServer) distributed_join.JoinContext {
        return .{
            .ptr = self,
            .vtable = &join_context_vtable,
        };
    }

    const join_context_vtable = distributed_join.JoinContext.VTable{
        .admin_snapshot = joinCtxAdminSnapshot,
        .free_admin_snapshot = joinCtxFreeAdminSnapshot,
        .local_table_stats = joinCtxLocalTableStats,
        .get_join_shuffle_lease = joinCtxGetJoinShuffleLease,
        .upsert_join_shuffle_lease = joinCtxUpsertJoinShuffleLease,
        .remove_join_shuffle_lease = joinCtxRemoveJoinShuffleLease,
        .execute_plain_query = joinCtxExecutePlainQuery,
        .execute_query_dispatch = joinCtxExecuteQueryDispatch,
        .build_owned_search_request = joinCtxBuildOwnedSearchRequest,
        .ensure_foreign_registry = joinCtxEnsureForeignRegistry,
    };

    fn joinCtxAdminSnapshot(ptr: *anyopaque) anyerror!?metadata_api.AdminSnapshot {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        return try self.source.adminSnapshot();
    }

    fn joinCtxFreeAdminSnapshot(ptr: *anyopaque, snapshot: *metadata_api.AdminSnapshot) void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        self.source.freeAdminSnapshot(snapshot);
    }

    fn joinCtxLocalTableStats(
        ptr: *anyopaque,
        table_name: []const u8,
        snapshot: *const metadata_api.AdminSnapshot,
    ) anyerror!?distributed_join.JoinTableStats {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        const table = tables_api.findTableByName(snapshot, table_name) orelse return null;
        var statuses = (try self.localTableRuntimeStatusesWithSnapshot(table_name, snapshot)) orelse return null;
        defer statuses.deinit(self.alloc);

        var status_by_group = std.AutoHashMapUnmanaged(u64, *const runtime_status.LocalTableRuntimeStatus).empty;
        defer status_by_group.deinit(self.alloc);
        try status_by_group.ensureTotalCapacity(
            self.alloc,
            std.math.cast(u32, statuses.items.len) orelse return error.TooManyRuntimeStatuses,
        );
        for (statuses.items) |*status| {
            status_by_group.putAssumeCapacity(status.group_id, status);
        }

        var stats: distributed_join.JoinTableStats = .{};
        var all_sizes_known = true;
        for (snapshot.ranges) |range| {
            if (range.table_id != table.table_id) continue;
            const status = status_by_group.get(range.group_id) orelse return null;
            if (!runtime_status.statusRuntimeFresh(status.*)) return null;
            stats.row_count +|= @max(status.stats.source_doc_count, status.stats.doc_count);
            if (status.disk_bytes_known) {
                stats.size_bytes +|= status.disk_bytes;
            } else {
                all_sizes_known = false;
            }
            stats.shard_count += 1;
        }
        if (stats.shard_count == 0) return null;
        stats.row_count_known = true;
        stats.size_bytes_known = all_sizes_known;
        return stats;
    }

    fn joinCtxGetJoinShuffleLease(ptr: *anyopaque, job_id: u64) anyerror!?metadata_table_manager.ShuffleJoinLeaseRecord {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        return try self.source.getJoinShuffleLease(job_id);
    }

    fn joinCtxUpsertJoinShuffleLease(ptr: *anyopaque, record: metadata_table_manager.ShuffleJoinLeaseRecord) anyerror!void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        _ = try self.source.upsertJoinShuffleLease(record);
    }

