test "api http server durably retries table repair job when background submit is closing" {
    if (@import("builtin").os.tag == .freestanding) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    var runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(alloc, .{});
    defer runtime.deinit();

    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var server = ApiHttpServer.init(alloc, .{
        .backend_runtime = runtime.ptr(),
    }, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, null);
    defer server.deinit();

    const started = try server.repair_job_store.startJob(alloc, "docs", .{
        .target = "artifact",
        .limit = 1,
    });
    defer alloc.free(started);
    var parsed_started = try std.json.parseFromSlice(repair_jobs.JobState, alloc, started, .{ .ignore_unknown_fields = true });
    defer parsed_started.deinit();

    const begin = try server.repair_job_store.beginAdvance(alloc, parsed_started.value);
    defer alloc.free(begin.encoded);
    try std.testing.expect(begin.started);
    var parsed_running = try std.json.parseFromSlice(repair_jobs.JobState, alloc, begin.encoded, .{ .ignore_unknown_fields = true });
    defer parsed_running.deinit();

    runtime.ptr().durable_jobs.closeOwner(server.repair_job_owner_id);
    const updated = (try server.submitTableRepairJobPass("docs", begin.encoded, parsed_running.value.job_id)).?;
    defer alloc.free(updated);

    var parsed_updated = try std.json.parseFromSlice(repair_jobs.JobState, alloc, updated, .{ .ignore_unknown_fields = true });
    defer parsed_updated.deinit();
    try std.testing.expectEqualStrings("queued", parsed_updated.value.phase);
    try std.testing.expectEqualStrings("BackgroundOwnerClosing", parsed_updated.value.last_error.?);
    try std.testing.expect(parsed_updated.value.next_retry_at_millis > parsed_updated.value.last_updated_at_millis);
}

test "api maintenance resumes recovered durable named index cancellation without client advance" {
    const alloc = std.testing.allocator;
    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };
    const FakeWrites = struct {
        calls: usize = 0,

        fn batch(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) anyerror!?void {
            return null;
        }

        fn repair(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            req: db_mod.types.ArtifactRepairRunRequest,
            _: db_mod.types.ArtifactRepairRunOptions,
        ) anyerror!?db_mod.types.ArtifactRepairResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expectEqual(db_mod.types.RepairTarget.index, req.target);
            try std.testing.expectEqual(db_mod.types.IndexRepairControl.pause_automatic, req.control.?);
            self.calls += 1;
            return .{
                .scanned = 1,
                .groups_scanned = 1,
                .controls_applied = 1,
            };
        }

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .repair_artifact_issues_controlled = repair,
                },
            };
        }
    };

    var writes = FakeWrites{};
    var server = ApiHttpServer.init(alloc, .{}, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, writes.source());
    defer server.deinit();

    const started = try server.repair_job_store.startJob(alloc, "docs", .{
        .target = "index",
        .index = "semantic",
    });
    defer alloc.free(started);
    var parsed_started = try std.json.parseFromSlice(repair_jobs.JobState, alloc, started, .{ .ignore_unknown_fields = true });
    defer parsed_started.deinit();
    const cancelling = try server.repair_job_store.requestCancel(alloc, parsed_started.value);
    defer alloc.free(cancelling);

    try server.runSessionMaintenanceOnce();
    try std.testing.expectEqual(@as(usize, 1), writes.calls);
    const finished = (try server.repair_job_store.loadJobAlloc(alloc, parsed_started.value.job_id)).?;
    defer alloc.free(finished);
    var parsed_finished = try std.json.parseFromSlice(repair_jobs.JobState, alloc, finished, .{ .ignore_unknown_fields = true });
    defer parsed_finished.deinit();
    try std.testing.expectEqualStrings("cancelled", parsed_finished.value.phase);
}

fn base64UrlDecodeAlloc(alloc: std.mem.Allocator, value: []const u8) ![]u8 {
    const size = std.base64.url_safe_no_pad.Decoder.calcSizeForSlice(value) catch return error.Unauthorized;
    const out = try alloc.alloc(u8, size);
    errdefer alloc.free(out);
    std.base64.url_safe_no_pad.Decoder.decode(out, value) catch return error.Unauthorized;
    return out;
}

fn constantTimeEql(lhs: []const u8, rhs: []const u8) bool {
    if (lhs.len != rhs.len) return false;
    var diff: u8 = 0;
    for (lhs, rhs) |left, right| diff |= left ^ right;
    return diff == 0;
}

fn jsonStringField(value: ?std.json.Value) ?[]const u8 {
    const present = value orelse return null;
    return jsonStringValue(present);
}

fn jsonStringValue(value: std.json.Value) ?[]const u8 {
    return switch (value) {
        .string => |string| string,
        else => null,
    };
}

fn jsonIntegerField(value: ?std.json.Value) ?i64 {
    const present = value orelse return null;
    return jsonIntegerValue(present);
}

fn jsonIntegerValue(value: std.json.Value) ?i64 {
    return switch (value) {
        .integer => |integer| integer,
        else => null,
    };
}

fn jsonBoolField(value: ?std.json.Value) bool {
    const present = value orelse return false;
    return jsonBoolValue(present);
}

fn jsonBoolValue(value: std.json.Value) bool {
    return switch (value) {
        .bool => |boolean| boolean,
        else => false,
    };
}

fn trustedPrincipalPermissionsFromPayload(alloc: std.mem.Allocator, payload: std.json.ObjectMap) ![]usermgr.Permission {
    var out = std.ArrayList(usermgr.Permission).empty;
    errdefer {
        for (out.items) |*permission| permission.deinit(alloc);
        out.deinit(alloc);
    }

    if (jsonBoolField(payload.get("admin"))) {
        try out.append(alloc, try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin));
        return try out.toOwnedSlice(alloc);
    }

    const tables_value = payload.get("tables");
    const operations_value = payload.get("operations");
    if (operations_value == null or operations_value.? != .array or operations_value.?.array.items.len == 0) {
        return try out.toOwnedSlice(alloc);
    }

    if (tables_value == null or tables_value.? != .array or tables_value.?.array.items.len == 0) {
        try appendTrustedPrincipalPermissionsForTable(alloc, &out, "*", operations_value.?.array.items);
    } else {
        for (tables_value.?.array.items) |table_value| {
            const table = jsonStringValue(table_value) orelse continue;
            if (table.len == 0) continue;
            try appendTrustedPrincipalPermissionsForTable(alloc, &out, table, operations_value.?.array.items);
        }
    }
    return try out.toOwnedSlice(alloc);
}

fn appendTrustedPrincipalPermissionsForTable(
    alloc: std.mem.Allocator,
    out: *std.ArrayList(usermgr.Permission),
    table: []const u8,
    operation_values: []const std.json.Value,
) !void {
    for (operation_values) |operation_value| {
        const operation = jsonStringValue(operation_value) orelse continue;
        if (std.mem.eql(u8, operation, "read")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .read));
        } else if (std.mem.eql(u8, operation, "write")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .write));
        } else if (std.mem.eql(u8, operation, "admin")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .admin));
        } else if (std.mem.eql(u8, operation, "*")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .read));
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .write));
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .admin));
        }
    }
}

fn trustedPrincipalRowFiltersFromPayload(alloc: std.mem.Allocator, payload: std.json.ObjectMap) ![]usermgr.RowFilterEntry {
    const row_filter_value = payload.get("row_filter") orelse return try alloc.alloc(usermgr.RowFilterEntry, 0);
    if (row_filter_value != .object) return error.Unauthorized;
    var out = std.ArrayList(usermgr.RowFilterEntry).empty;
    errdefer {
        for (out.items) |*entry| entry.deinit(alloc);
        out.deinit(alloc);
    }
    var it = row_filter_value.object.iterator();
    while (it.next()) |entry| {
        const filter_json = try std.json.Stringify.valueAlloc(alloc, entry.value_ptr.*, .{});
        defer alloc.free(filter_json);
        try out.append(alloc, try usermgr.RowFilterEntry.initOwned(alloc, entry.key_ptr.*, filter_json));
    }
    return try out.toOwnedSlice(alloc);
}

fn applyAuthenticatedIdentityToJoinRequest(
    alloc: std.mem.Allocator,
    identity: AuthenticatedIdentity,
    join: *distributed_join.SupportedJoinRequest,
) !void {
    if (!permissionsAllow(identity.permissions, .table, join.right_table, .read)) return error.InvalidQueryRequest;

    const row_filter_json = try resolveEffectiveRowFilterJson(alloc, identity, join.right_table);
    defer if (row_filter_json) |value| alloc.free(value);
    if (row_filter_json) |value| {
        try distributed_join.applyRightTableRowFilterJson(alloc, join, value);
    }

    if (join.nested_join) |nested| {
        try applyAuthenticatedIdentityToJoinRequest(alloc, identity, nested);
    }
}

