test "api http public sort capability gate validates score-bearing source" {
    const runtime_schema = storage_schema.TableSchema{};
    const score_order = [_]db_mod.types.SortField{.{ .field = "_score", .desc = true }};

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &score_order,
        .full_text = .{ .match_all = {} },
    }, runtime_schema, &.{}));
    var diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("_score", diagnostic.field);
    try std.testing.expectEqualStrings("non_score_bearing_source", diagnostic.reason);
    try std.testing.expectEqualStrings("non_score_bearing_source", diagnostic.detail);

    try validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &score_order,
        .full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
    }, runtime_schema, &.{});

    const vector = [_]f32{ 0.1, 0.2 };
    const id_cursor = [_]std.json.Value{.{ .string = "doc:1" }};
    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .search_after = &id_cursor,
        .dense = .{ .vector = &vector, .k = 10 },
    }, runtime_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("*", diagnostic.field);
    try std.testing.expectEqualStrings("approximate_candidate_source", diagnostic.reason);

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &score_order,
        .dense = .{ .vector = &vector, .k = 10 },
    }, runtime_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("_score", diagnostic.field);
    try std.testing.expectEqualStrings("approximate_candidate_source", diagnostic.reason);

    const id_order = [_]db_mod.types.SortField{.{ .field = "_id", .desc = false }};
    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &id_order,
        .dense = .{ .vector = &vector, .k = 10 },
    }, runtime_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("_id", diagnostic.field);
    try std.testing.expectEqualStrings("approximate_candidate_source", diagnostic.reason);

    const templates = [_]storage_schema.DynamicTemplate{.{
        .name = "created_at",
        .path_match = "created_at",
        .mapping = .{
            .field_type = .datetime,
            .doc_values = true,
            .sortable = true,
            .analyzer = "keyword",
        },
    }};
    const mapped_schema = storage_schema.TableSchema{ .dynamic_templates = &templates };
    const combined_order = [_]db_mod.types.SortField{
        .{ .field = "_score", .desc = true },
        .{ .field = "created_at", .desc = true },
    };

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &combined_order,
        .full_text = .{ .match_all = {} },
    }, mapped_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("_score", diagnostic.field);
    try std.testing.expectEqualStrings("non_score_bearing_source", diagnostic.reason);

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &combined_order,
        .full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
    }, mapped_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("created_at", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);

    const field_order = [_]db_mod.types.SortField{.{ .field = "created_at", .desc = true }};
    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedQueryRequest, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &field_order,
        .dense = .{ .vector = &vector, .k = 10 },
    }, mapped_schema, &.{}));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("created_at", diagnostic.field);
    try std.testing.expectEqualStrings("approximate_candidate_source", diagnostic.reason);
}

test "api http public sort capability gate fails closed for uncovered observed dynamic fields" {
    const runtime_schema = storage_schema.TableSchema{};
    var covered = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    covered.doc_value_coverage = "covered";
    covered.queryability_state = "queryable";
    storage_schema.refreshSortLifecycleState(&covered);
    const covered_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{covered})[0..]),
    };
    const price_order = [_]db_mod.types.SortField{.{ .field = "price" }};
    try validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{covered_set});

    const declared = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    const declared_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{declared})[0..]),
    };
    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{declared_set}));
    var diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{ covered_set, declared_set }));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);

    const declared_other_index = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    const declared_other_index_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v1"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{declared_other_index})[0..]),
    };
    try validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{ covered_set, declared_other_index_set });

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
    }, runtime_schema, &.{ covered_set, declared_other_index_set }));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);
}

test "api http server serves extension catalog reads" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_extension_packages = 1,
                .projected_installed_extensions = 1,
                .projected_extension_members = 2,
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 77, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .extension_packages = @constCast((&[_]extension_domain.PackageManifest{.{
                    .name = "memoryaf",
                    .version = "1.0.0",
                    .digest = "sha256:abc",
                    .trusted = true,
                    .install = .{
                        .scopes_supported = &.{.table},
                        .objects = &.{.{ .kind = .mcp_tool, .name = "recall" }},
                    },
                }})[0..]),
                .installed_extensions = @constCast((&[_]extension_domain.InstalledExtension{.{
                    .name = "memoryaf",
                    .package_name = "memoryaf",
                    .package_version = "1.0.0",
                    .package_digest = "sha256:abc",
                    .scope = .{ .kind = .table, .table_name = "memories" },
                    .status = .ready,
                }})[0..]),
                .extension_members = @constCast((&[_]extension_domain.ExtensionMember{
                    .{
                        .extension_name = "memoryaf",
                        .scope = .{ .kind = .table, .table_name = "memories" },
                        .object_kind = .data_shape,
                        .object_name = "memory_record",
                    },
                    .{
                        .extension_name = "memoryaf",
                        .scope = .{ .kind = .table, .table_name = "memories" },
                        .object_kind = .mcp_tool,
                        .object_name = "recall",
                        .table_name = "memories",
                    },
                })[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);

    var packages_resp = try server.handle(.{ .method = .GET, .uri = routes.Routes.extensions_v1_packages });
    defer packages_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), packages_resp.status);
    var packages = try std.json.parseFromSlice([]extension_domain.PackageManifest, std.testing.allocator, packages_resp.body, .{ .ignore_unknown_fields = true });
    defer packages.deinit();
    try std.testing.expectEqual(@as(usize, 1), packages.value.len);
    try std.testing.expectEqualStrings("memoryaf", packages.value[0].name);

    var package_resp = try server.handle(.{ .method = .GET, .uri = "/extensions/v1/packages/memoryaf/versions/1.0.0" });
    defer package_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), package_resp.status);
    var package = try std.json.parseFromSlice(extension_domain.PackageManifest, std.testing.allocator, package_resp.body, .{ .ignore_unknown_fields = true });
    defer package.deinit();
    try std.testing.expectEqualStrings("sha256:abc", package.value.digest);

    var installed_resp = try server.handle(.{ .method = .GET, .uri = "/extensions/v1/installed/memoryaf" });
    defer installed_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), installed_resp.status);
    var installed = try std.json.parseFromSlice(extension_domain.InstalledExtension, std.testing.allocator, installed_resp.body, .{ .ignore_unknown_fields = true });
    defer installed.deinit();
    try std.testing.expectEqualStrings("1.0.0", installed.value.package_version);

    var objects_resp = try server.handle(.{ .method = .GET, .uri = "/extensions/v1/installed/memoryaf/objects" });
    defer objects_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), objects_resp.status);
    var objects = try std.json.parseFromSlice([]extension_domain.ExtensionMember, std.testing.allocator, objects_resp.body, .{ .ignore_unknown_fields = true });
    defer objects.deinit();
    try std.testing.expectEqual(@as(usize, 2), objects.value.len);

    var missing_resp = try server.handle(.{ .method = .GET, .uri = "/extensions/v1/installed/missing" });
    defer missing_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 404), missing_resp.status);

    var write_resp = try server.handle(.{ .method = .POST, .uri = "/extensions/v1/installed/memoryaf/update", .body = "{}" });
    defer write_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 405), write_resp.status);
}

test "api http server validates writes against extension data shape members" {
    const alloc = std.testing.allocator;
    const shape_schema = "{\"default_type\":\"doc\",\"enforce_types\":true,\"document_schemas\":{\"doc\":{\"schema\":{\"type\":\"object\",\"properties\":{\"body\":{\"type\":\"text\"},\"kind\":{\"type\":\"keyword\"}}}}}}";

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_tables = 1,
                .projected_extension_members = 1,
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 77, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 10,
                    .name = "memories",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .extension_members = @constCast((&[_]extension_domain.ExtensionMember{.{
                    .extension_name = "memoryaf",
                    .scope = .{ .kind = .table, .table_name = "memories" },
                    .object_kind = .data_shape,
                    .object_name = "memory_record",
                    .shape_kind = .document,
                    .table_name = "memories",
                    .owner_metadata_json = shape_schema,
                }})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);

    try server.validateTableWritesAgainstSchema("memories", &[_]db_mod.types.BatchWrite{.{
        .key = "doc:a",
        .value = "{\"body\":\"remember this\",\"kind\":\"note\"}",
    }});

    try std.testing.expectError(error.InvalidBatchRequest, server.validateTableWritesAgainstSchema("memories", &[_]db_mod.types.BatchWrite{.{
        .key = "doc:b",
        .value = "{\"body\":\"remember this\",\"unexpected\":\"owned by no shape\"}",
    }}));

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/extension-shape-batch", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    var table_source = table_writes.BoundTableWriteSource.init("memories", &db);
    var routed_server = ApiHttpServer.init(alloc, .{}, source.iface(), null, table_source.source());

    const valid_body = try test_contract_helpers.normalizeBatchRequest(alloc, "{\"inserts\":{\"doc:c\":{\"body\":\"remember this\",\"kind\":\"note\"}}}");
    defer alloc.free(valid_body);
    var valid_resp = try routed_server.handle(.{
        .method = .POST,
        .uri = "/tables/memories/batch",
        .content_type = "application/json",
        .body = valid_body,
    });
    defer valid_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), valid_resp.status);

    const invalid_body = try test_contract_helpers.normalizeBatchRequest(alloc, "{\"inserts\":{\"doc:d\":{\"body\":\"remember this\",\"unexpected\":\"owned by no shape\"}}}");
    defer alloc.free(invalid_body);
    var invalid_resp = try routed_server.handle(.{
        .method = .POST,
        .uri = "/tables/memories/batch",
        .content_type = "application/json",
        .body = invalid_body,
    });
    defer invalid_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), invalid_resp.status);
}

test "api http server exposes storage status and asynchronous maintenance jobs" {
    const maintenance_mod = @import("../storage/maintenance.zig");
    const FakeStatus = struct {
        fn iface(self: *@This()) StatusSource {
            return .{ .ptr = self, .vtable = &.{ .status = status } };
        }
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };
    const FakeMaintenance = struct {
        fn source(self: *@This()) maintenance_mod.Source {
            return .{ .ptr = self, .vtable = &.{ .status = status, .run = run } };
        }
        fn status(_: *anyopaque) maintenance_mod.Status {
            return .{ .engine = "lite", .format = "aflite", .fsync = true, .maintenance = .{ .check = true, .compact = true, .vacuum = true, .online = true } };
        }
        fn run(_: *anyopaque, operation: maintenance_mod.Operation, cancel: *const maintenance_mod.CancelToken) anyerror!maintenance_mod.Result {
            try cancel.check();
            return switch (operation) {
                .check => .{ .valid = true, .file_size = 4096 },
                .compact, .vacuum => .{ .before_size = 8192, .after_size = 4096, .reclaimed_bytes = 4096 },
            };
        }
    };

    var status_source = FakeStatus{};
    var maintenance_source = FakeMaintenance{};
    var backend_runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(std.testing.allocator, .{ .backend = .io_threaded });
    defer backend_runtime.deinit();
    var coordinator = try maintenance_mod.Coordinator.init(std.testing.allocator, maintenance_source.source(), backend_runtime.ptr());
    defer coordinator.deinit();
    var server = ApiHttpServer.init(std.testing.allocator, .{
        .storage_maintenance = &coordinator,
        .admin_bearer_token = "maintenance-secret",
    }, status_source.iface(), null, null);
    defer server.deinit();

    var status_resp = try server.handle(.{ .method = .GET, .uri = routes.Routes.status });
    defer status_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), status_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, status_resp.body, "\"engine\":\"lite\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, status_resp.body, "\"vacuum\":true") != null);

    const headers = [_]http_common.RequestHeader{.{ .name = "Idempotency-Key", .value = "check-1" }};
    var unauthorized_resp = try server.handle(.{ .method = .POST, .uri = admin_routes.maintenance_check, .headers = &headers });
    defer unauthorized_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 401), unauthorized_resp.status);

    var start_resp = try server.handle(.{
        .method = .POST,
        .uri = admin_routes.maintenance_check,
        .headers = &headers,
        .authorization = "Bearer maintenance-secret",
    });
    defer start_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 202), start_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, start_resp.body, "\"operation\":\"check\"") != null);
    const MaintenanceStart = struct { job_id: u64 };
    var parsed_start = try std.json.parseFromSlice(MaintenanceStart, std.testing.allocator, start_resp.body, .{ .ignore_unknown_fields = true });
    defer parsed_start.deinit();
    const maintenance_job_id = parsed_start.value.job_id;
    const maintenance_job_path = try std.fmt.allocPrint(std.testing.allocator, "{s}{d}", .{ admin_routes.maintenance_jobs_prefix, maintenance_job_id });
    defer std.testing.allocator.free(maintenance_job_path);

    var replay_resp = try server.handle(.{
        .method = .POST,
        .uri = admin_routes.maintenance_check,
        .headers = &headers,
        .authorization = "Bearer maintenance-secret",
    });
    defer replay_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 202), replay_resp.status);
    const expected_job_id = try std.fmt.allocPrint(std.testing.allocator, "\"job_id\":{d}", .{maintenance_job_id});
    defer std.testing.allocator.free(expected_job_id);
    try std.testing.expect(std.mem.indexOf(u8, replay_resp.body, expected_job_id) != null);

    while (coordinator.get(maintenance_job_id).?.state != .succeeded) std.Thread.yield() catch {};
    var get_resp = try server.handle(.{
        .method = .GET,
        .uri = maintenance_job_path,
        .authorization = "Bearer maintenance-secret",
    });
    defer get_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), get_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, get_resp.body, "\"valid\":true") != null);

    var cancel_resp = try server.handle(.{
        .method = .DELETE,
        .uri = maintenance_job_path,
        .authorization = "Bearer maintenance-secret",
    });
    defer cancel_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 202), cancel_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, cancel_resp.body, "\"state\":\"succeeded\"") != null);
}

test "api http server dispatches extension lifecycle mutations" {
    const FakeSource = struct {
        install_called: bool = false,
        install_dry_run: bool = false,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .install_extension = installExtension,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }

        fn installExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.InstallExtensionRequest) !extension_domain.InstalledExtension {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.install_called = true;
            self.install_dry_run = req.dry_run;
            return .{
                .name = try alloc.dupe(u8, name),
                .package_name = try alloc.dupe(u8, name),
                .package_version = try alloc.dupe(u8, if (req.version.len > 0) req.version else "1.0.0"),
                .package_digest = try alloc.dupe(u8, "sha256:test"),
                .scope = .{
                    .kind = req.scope.kind,
                    .table_name = if (req.scope.table_name.len > 0) try alloc.dupe(u8, req.scope.table_name) else "",
                },
                .config_json = try alloc.dupe(u8, req.config_json),
                .granted_capabilities = &.{},
                .installed_at_epoch_ms = 123,
                .status = .ready,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);
    var install_resp = try server.handle(.{
        .method = .POST,
        .uri = "/extensions/v1/installed/memoryaf",
        .content_type = "application/json",
        .body = "{\"version\":\"1.2.3\",\"scope\":{\"kind\":\"table\",\"table_name\":\"memories\"},\"config_json\":\"{\\\"tenant\\\":\\\"acme\\\"}\",\"dry_run\":true}",
    });
    defer install_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), install_resp.status);
    try std.testing.expect(source.install_called);
    try std.testing.expect(source.install_dry_run);
    var installed = try std.json.parseFromSlice(extension_domain.InstalledExtension, std.testing.allocator, install_resp.body, .{ .ignore_unknown_fields = true });
    defer installed.deinit();
    try std.testing.expectEqualStrings("memoryaf", installed.value.name);
    try std.testing.expectEqualStrings("1.2.3", installed.value.package_version);
    try std.testing.expectEqualStrings("memories", installed.value.scope.table_name);
}

