test "api runtime status upsert keeps one authoritative observation per group" {
    const alloc = std.testing.allocator;
    var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
    var item_indexes = std.AutoHashMapUnmanaged(u64, usize).empty;
    defer item_indexes.deinit(alloc);
    defer {
        for (items.items) |*item| item.deinit(alloc);
        items.deinit(alloc);
    }

    var remote = runtime_status.LocalTableRuntimeStatus{
        .group_id = 7001,
        .metadata = .{
            .source = .remote_store,
            .freshness = .fresh,
            .topology_generation = 4,
            .lsm_root_generation = 9,
            .status_generation = 3,
            .store_id = 5,
            .node_id = 6,
            .updated_at_ns = 100,
        },
        .stats = .{},
    };
    try ApiHttpServer.upsertRuntimeStatus(alloc, &items, &item_indexes, &remote);
    try std.testing.expectEqual(@as(usize, 1), items.items.len);

    var stale_writer = runtime_status.LocalTableRuntimeStatus{
        .group_id = 7001,
        .metadata = .{
            .source = .live_writer_publish,
            .freshness = .fresh,
            .topology_generation = 3,
            .lsm_root_generation = 10,
            .status_generation = 10,
            .store_id = 5,
            .node_id = 6,
            .updated_at_ns = 200,
        },
        .stats = .{},
    };
    try ApiHttpServer.upsertRuntimeStatus(alloc, &items, &item_indexes, &stale_writer);
    try std.testing.expectEqual(@as(usize, 1), items.items.len);
    try std.testing.expectEqual(runtime_status.RuntimeStatusSource.remote_store, items.items[0].metadata.source);

    var current_writer = runtime_status.LocalTableRuntimeStatus{
        .group_id = 7001,
        .metadata = .{
            .source = .live_writer_publish,
            .freshness = .fresh,
            .topology_generation = 4,
            .lsm_root_generation = 9,
            .status_generation = 3,
            .store_id = 5,
            .node_id = 6,
            .updated_at_ns = 50,
        },
        .stats = .{},
    };
    try ApiHttpServer.upsertRuntimeStatus(alloc, &items, &item_indexes, &current_writer);
    try std.testing.expectEqual(@as(usize, 1), items.items.len);
    try std.testing.expectEqual(runtime_status.RuntimeStatusSource.live_writer_publish, items.items[0].metadata.source);

    var delayed_fresh = runtime_status.LocalTableRuntimeStatus{
        .group_id = 7001,
        .metadata = .{
            .source = .live_writer_publish,
            .freshness = .fresh,
            .topology_generation = 4,
            .lsm_root_generation = 9,
            .status_generation = 2,
            .store_id = 5,
            .node_id = 6,
            .updated_at_ns = 500,
        },
        .stats = .{},
    };
    try ApiHttpServer.upsertRuntimeStatus(alloc, &items, &item_indexes, &delayed_fresh);
    try std.testing.expectEqual(@as(u64, 3), items.items[0].metadata.status_generation);

    var newer_stale = runtime_status.LocalTableRuntimeStatus{
        .group_id = 7001,
        .metadata = .{
            .source = .cached_snapshot,
            .freshness = .stale,
            .topology_generation = 4,
            .lsm_root_generation = 9,
            .status_generation = 4,
            .store_id = 5,
            .node_id = 6,
            .updated_at_ns = 25,
        },
        .stats = .{},
    };
    try ApiHttpServer.upsertRuntimeStatus(alloc, &items, &item_indexes, &newer_stale);
    try std.testing.expectEqual(@as(u64, 4), items.items[0].metadata.status_generation);
    try std.testing.expectEqual(runtime_status.RuntimeStatusFreshness.stale, items.items[0].metadata.freshness);
}

test "api index status uses read runtime status without consulting write source" {
    const alloc = std.testing.allocator;

    const Response = struct {
        const Stats = struct {
            doc_count: ?u64 = null,
            total_indexed: ?u64 = null,
            node_count: ?u64 = null,
            replay_applied_sequence: ?u64 = null,
            replay_target_sequence: ?u64 = null,
            replay_catch_up_required: ?bool = null,
            catch_up_active: ?bool = null,
            catch_up_applied_sequence: ?u64 = null,
            catch_up_target_sequence: ?u64 = null,
        };

        status: Stats,
        shard_status: ?struct {
            @"10": ?Stats = null,
        } = null,
    };

    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .cached_admin_snapshot = cachedAdminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .indexes_json = "{\"vec\":{\"type\":\"embeddings\",\"dimension\":3}}",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{.{
                    .group_id = 10,
                    .table_id = 1,
                    .start_key = "",
                    .end_key = null,
                }})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn cachedAdminSnapshot(ptr: *anyopaque) !?metadata_api.AdminSnapshot {
            return try adminSnapshot(ptr);
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const FakeReads = struct {
        status_calls: std.atomic.Value(u32) = .init(0),

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                    .local_runtime_statuses = localRuntimeStatuses,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) !?table_reads.LookupResponse {
            return error.TestUnexpectedResult;
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) !?table_reads.ScanResponse {
            return error.TestUnexpectedResult;
        }

        fn query(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) !?query_api.QueryResponse {
            return error.TestUnexpectedResult;
        }

        fn localRuntimeStatuses(ptr: *anyopaque, inner_alloc: std.mem.Allocator, _: []const u8) !?runtime_status.LocalTableRuntimeStatuses {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.status_calls.fetchAdd(1, .monotonic);
            const indexes = try inner_alloc.alloc(db_mod.types.DBIndexStats, 1);
            errdefer inner_alloc.free(indexes);
            indexes[0] = .{
                .name = try inner_alloc.dupe(u8, "vec"),
                .kind = .dense_vector,
                .doc_count = 9,
                .node_count = 17,
                .replay_applied_sequence = 3,
                .replay_target_sequence = 7,
                .replay_catch_up_required = true,
            };

            const items = try inner_alloc.alloc(runtime_status.LocalTableRuntimeStatus, 1);
            errdefer {
                db_mod.types.freeDBStats(inner_alloc, .{
                    .doc_count = 9,
                    .index_count = 1,
                    .indexes = indexes,
                });
                inner_alloc.free(items);
            }
            items[0] = .{
                .group_id = 10,
                .metadata = .{ .source = .cached_snapshot, .freshness = .fresh },
                .stats = .{
                    .doc_count = 9,
                    .index_count = 1,
                    .indexes = indexes,
                },
            };
            return .{ .items = items };
        }
    };

    const FakeWrites = struct {
        status_calls: std.atomic.Value(u32) = .init(0),

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .local_runtime_statuses = localRuntimeStatuses,
                },
            };
        }

        fn batch(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.BatchRequest) !?void {
            return;
        }

        fn localRuntimeStatuses(ptr: *anyopaque, inner_alloc: std.mem.Allocator, _: []const u8) !?runtime_status.LocalTableRuntimeStatuses {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.status_calls.fetchAdd(1, .monotonic);
            const indexes = try inner_alloc.alloc(db_mod.types.DBIndexStats, 1);
            errdefer inner_alloc.free(indexes);
            indexes[0] = .{
                .name = try inner_alloc.dupe(u8, "vec"),
                .kind = .dense_vector,
                .doc_count = 12,
                .node_count = 23,
                .replay_applied_sequence = 5,
                .replay_target_sequence = 11,
                .replay_catch_up_required = true,
            };

            const items = try inner_alloc.alloc(runtime_status.LocalTableRuntimeStatus, 1);
            errdefer {
                db_mod.types.freeDBStats(inner_alloc, .{
                    .doc_count = 12,
                    .index_count = 1,
                    .indexes = indexes,
                });
                inner_alloc.free(items);
            }
            items[0] = .{
                .group_id = 10,
                .stats = .{
                    .doc_count = 12,
                    .index_count = 1,
                    .indexes = indexes,
                },
            };
            return .{ .items = items };
        }
    };

    var source = FakeSource{};
    var reads = FakeReads{};
    var writes = FakeWrites{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), reads.source(), writes.source());

    var resp = try server.handle(.{
        .method = .GET,
        .uri = "/tables/docs/indexes/vec",
    });
    defer resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), resp.status);
    try std.testing.expectEqual(@as(u32, 1), reads.status_calls.load(.monotonic));
    try std.testing.expectEqual(@as(u32, 0), writes.status_calls.load(.monotonic));
    var parsed = try std.json.parseFromSlice(Response, alloc, resp.body, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    try std.testing.expectEqual(@as(?u64, 9), parsed.value.status.doc_count);
    try std.testing.expectEqual(@as(?u64, 9), parsed.value.status.total_indexed);
    try std.testing.expectEqual(@as(?u64, 17), parsed.value.status.node_count);
    try std.testing.expectEqual(@as(?u64, 7), parsed.value.status.replay_applied_sequence);
    try std.testing.expectEqual(@as(?u64, 7), parsed.value.status.replay_target_sequence);
    try std.testing.expectEqual(@as(?bool, false), parsed.value.status.replay_catch_up_required);
    const shard_status = parsed.value.shard_status.?;
    const shard_10 = shard_status.@"10".?;
    try std.testing.expectEqual(@as(?u64, 9), shard_10.doc_count);
    try std.testing.expectEqual(@as(?u64, 3), shard_10.replay_applied_sequence);
    try std.testing.expectEqual(@as(?u64, 7), shard_10.replay_target_sequence);
    try std.testing.expectEqual(@as(?bool, true), shard_10.replay_catch_up_required);
}

test "api index status refreshes synthetic configured index status from write source" {
