test "remote runtime status reports replay debt separately from active catch-up" {
    const alloc = std.testing.allocator;

    const report = metadata_table_manager.RuntimeGroupStatusReport{
        .table_id = 1,
        .table_name = "docs",
        .group_id = 10,
        .store_id = 20,
        .node_id = 30,
        .updated_at_ns = 99,
        .freshness = "fresh",
        .doc_count = 56_250,
        .index_count = 1,
        .enrichment = .{
            .projection_checkpoint_status = "rebuilding",
            .processed_requests = 17,
            .worker_started = true,
            .stalled = true,
        },
        .async_dense_catch_up_active = false,
        .doc_identity = .{
            .namespace_table_id = 1,
            .namespace_shard_id = 10,
            .namespace_range_id = 1001,
            .next_ordinal = 44,
            .live_ordinals = 40,
            .rebuild_required = true,
        },
        .doc_set_planning = .{
            .resolved_set_count = 7,
            .ordinal_list_count = 3,
            .missing_ordinal_coverage_count = 1,
            .stale_identity_generation_rejection_count = 2,
        },
        .indexes = @constCast((&[_]metadata_table_manager.RuntimeIndexStatusReport{.{
            .name = "vec",
            .kind = "dense_vector",
            .doc_count = 56_250,
            .node_count = 756,
            .coverage_produced_count = 31,
            .coverage_skipped_count = 7,
            .coverage_terminal_failed_count = 2,
            .coverage_config_hash = 0x1234,
            .coverage_summary_ready = true,
            .replay_applied_sequence = 225,
            .replay_target_sequence = 300,
            .replay_catch_up_required = true,
        }})[0..]),
    };

    var status = try ApiHttpServer.localRuntimeStatusFromRemoteReport(alloc, report);
    defer status.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), status.stats.indexes.len);
    const index = status.stats.indexes[0];
    try std.testing.expectEqual(@as(u64, 225), index.replay_applied_sequence);
    try std.testing.expectEqual(@as(u64, 300), index.replay_target_sequence);
    try std.testing.expectEqual(true, index.replay_catch_up_required);
    try std.testing.expectEqual(false, index.catch_up_active);
    try std.testing.expectEqual(@as(u64, 225), index.catch_up_applied_sequence);
    try std.testing.expectEqual(@as(u64, 300), index.catch_up_target_sequence);
    try std.testing.expectEqual(@as(u64, 31), index.coverage_produced_count);
    try std.testing.expectEqual(@as(u64, 7), index.coverage_skipped_count);
    try std.testing.expectEqual(@as(u64, 2), index.coverage_terminal_failed_count);
    try std.testing.expectEqual(@as(u64, 0x1234), index.coverage_config_hash);
    try std.testing.expect(index.coverage_summary_ready);
    try std.testing.expectEqual(@as(u64, 40), status.stats.source_doc_count);
    try std.testing.expectEqual(@as(u64, 1), status.stats.doc_identity.namespace_table_id);
    try std.testing.expectEqual(@as(u64, 10), status.stats.doc_identity.namespace_shard_id);
    try std.testing.expectEqual(@as(u64, 1001), status.stats.doc_identity.namespace_range_id);
    try std.testing.expectEqual(@as(u32, 44), status.stats.doc_identity.next_ordinal);
    try std.testing.expect(status.stats.doc_identity.rebuild_required);
    try std.testing.expectEqual(@as(u64, 7), status.stats.doc_set_planning.resolved_set_count);
    try std.testing.expectEqual(@as(u64, 3), status.stats.doc_set_planning.ordinal_list_count);
    try std.testing.expectEqual(@as(u64, 1), status.stats.doc_set_planning.missing_ordinal_coverage_count);
    try std.testing.expectEqual(@as(u64, 2), status.stats.doc_set_planning.stale_identity_generation_rejection_count);
    try std.testing.expect(status.stats.enrichment.worker_started);
    try std.testing.expect(status.stats.enrichment.stalled);
    try std.testing.expectEqual(@as(u64, 17), status.stats.enrichment.processed_requests);
    try std.testing.expectEqualStrings("rebuilding", status.stats.enrichment.projection_checkpoint_status);
}

test "table storage status sums complete fresh shard disk usage" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface() StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var group_10 = [_]metadata_table_manager.RuntimeGroupStatusReport{.{
        .table_id = 1,
        .table_name = "docs",
        .group_id = 10,
        .store_id = 20,
        .node_id = 30,
        .source = "background_refresh",
        .freshness = "fresh",
        .doc_count = 4,
        .disk_bytes = 4096,
        .disk_bytes_known = true,
        .doc_identity = .{ .live_ordinals = 5 },
    }};
    var group_11 = [_]metadata_table_manager.RuntimeGroupStatusReport{.{
        .table_id = 1,
        .table_name = "docs",
        .group_id = 11,
        .store_id = 21,
        .node_id = 31,
        .source = "background_refresh",
        .freshness = "fresh",
        .doc_count = 6,
        .disk_bytes = 8192,
        .disk_bytes_known = true,
        .doc_identity = .{ .live_ordinals = 7 },
    }};
    var stores = [_]metadata_table_manager.StoreRecord{
        .{ .store_id = 20, .node_id = 30, .runtime_statuses = group_10[0..] },
        .{ .store_id = 21, .node_id = 31, .runtime_statuses = group_11[0..] },
    };
    var snapshot = metadata_api.AdminSnapshot{
        .status = .{ .metadata_group_id = 1, .metrics = .{} },
        .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
            .table_id = 1,
            .name = "docs",
            .indexes_json = tables_api.default_indexes_json,
            .placement_role = "data",
        }})[0..]),
        .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{
            .{ .group_id = 10, .table_id = 1, .start_key = "", .end_key = "m" },
            .{ .group_id = 11, .table_id = 1, .start_key = "m", .end_key = null },
        })[0..]),
        .stores = stores[0..],
        .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
        .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
        .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
    };
    var server = ApiHttpServer.init(alloc, .{}, FakeSource.iface(), null, null);

    const complete = (try server.bestEffortSingleTableStorageStatusWithSnapshot("docs", &snapshot)).?;
    try std.testing.expectEqual(false, complete.empty);
    try std.testing.expectEqual(@as(?u64, 12_288), complete.disk_usage);

    const join_stats = (try server.joinContext().localTableStats("docs", &snapshot)).?;
    try std.testing.expect(join_stats.row_count_known);
    try std.testing.expect(join_stats.size_bytes_known);
    try std.testing.expectEqual(@as(u64, 12), join_stats.row_count);
    try std.testing.expectEqual(@as(u64, 12_288), join_stats.size_bytes);
    try std.testing.expectEqual(@as(usize, 2), join_stats.shard_count);

    group_11[0].disk_bytes_known = false;
    const incomplete = (try server.bestEffortSingleTableStorageStatusWithSnapshot("docs", &snapshot)).?;
    try std.testing.expectEqual(@as(?u64, null), incomplete.disk_usage);
    const row_only_join_stats = (try server.joinContext().localTableStats("docs", &snapshot)).?;
    try std.testing.expect(row_only_join_stats.row_count_known);
    try std.testing.expect(!row_only_join_stats.size_bytes_known);
    try std.testing.expectEqual(@as(u64, 12), row_only_join_stats.row_count);

    snapshot.ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]);
