            .end_key = "m",
            .snapshot_path = "snap1/groups/1",
            .artifact_sha256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
        },
        .{
            .group_id = 2,
            .start_key = "m",
            .snapshot_path = "snap1/groups/2",
            .artifact_sha256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
        },
    };
    var multi_manifest = try backups_api.createManifest(alloc, "snap1", .native, &.{
        .table_id = 1,
        .name = "docs",
        .description = "docs table",
        .schema_json = "",
        .read_schema_json = "",
        .indexes_json = tables_api.default_indexes_json,
        .replication_sources_json = "[]",
    }, &multi_shards);
    defer multi_manifest.deinit(alloc);
    try backups_api.writeManifest(alloc, backup_root_abs, &multi_manifest);

    const FakeSource = struct {
        created: bool = false,
        dropped: bool = false,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .create_table = createTable,
                    .drop_table = dropTable,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const tables = if (self.created)
                @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .description = "docs table",
                    .indexes_json = tables_api.default_indexes_json,
                    .replication_sources_json = "[]",
                    .placement_role = "data",
                }})[0..])
            else
                @constCast((&[_]metadata_table_manager.TableRecord{})[0..]);
            const ranges = if (self.created)
                @constCast((&[_]metadata_table_manager.RangeRecord{.{
                    .group_id = 1,
                    .table_id = 1,
                    .start_key = "",
                    .end_key = null,
                }})[0..])
            else
                @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]);
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = tables,
                .ranges = ranges,
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
