    );
    defer snapshot_integrity.deinit(alloc);

    const shards = try alloc.alloc(backups_api.ShardSnapshot, 1);
    shards[0] = .{
        .group_id = 42,
        .start_key = try alloc.dupe(u8, ""),
        .end_key = null,
