    try publishTestCommittedClusterAttempt(
        alloc,
        backup_root_abs,
        "attempt-cluster-overwrite",
        "snap-cluster",
        "docs",
        table_backup_id,
        .native,
    );

    var backup_dir = try std.Io.Dir.openDirAbsolute(
        std.testing.io,
        backup_root_abs,
        .{ .iterate = true },
    );
    defer backup_dir.close(std.testing.io);
    const backup_dir_permissions = (try backup_dir.stat(std.testing.io)).permissions;
    try backup_dir.setPermissions(
        std.testing.io,
        backup_dir_permissions.setReadOnly(true),
    );
    defer backup_dir.setPermissions(std.testing.io, backup_dir_permissions) catch {};

    const State = struct {
        present: bool = true,
        restored: bool = false,
        definition_replaced: bool = false,
        metadata_drop_called: bool = false,
        local_drop_called: bool = false,
        restore_lifecycle_active: bool = false,
        restore_lifecycle_finished: bool = false,
        expected_backup_id: []const u8,
    };

    const FakeSource = struct {
        state: *State,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .create_table = createTable,
                    .replace_table_definition = replaceTableDefinition,
                    .drop_table = dropTable,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const tables = if (self.state.present)
                @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .description = "docs table",
                    .schema_json = "",
