    const installed = [_]extension_domain.InstalledExtension{.{
        .name = "memoryaf",
        .package_name = "memoryaf",
        .package_version = "1.0.0",
        .package_digest = "sha256:memory",
        .scope = .{ .kind = .table, .table_name = "docs" },
        .status = .ready,
    }};
    const members = [_]extension_domain.ExtensionMember{.{
        .extension_name = "memoryaf",
        .scope = .{ .kind = .table, .table_name = "docs" },
        .object_kind = .mcp_tool,
        .object_name = "recall",
    }};
    const dependencies = [_]extension_domain.ExtensionDependency{.{
        .extension_name = "memoryaf",
        .required_extension_name = "antfly_core",
        .package_name = "antfly_core",
    }};
    var cluster_manifest = try backups_api.createClusterManifestWithExtensions(
        alloc,
        "snap-cluster",
        location_uri,
        &.{cluster_entry},
        &installed,
        &members,
        &dependencies,
    );
    defer cluster_manifest.deinit(alloc);
    try backups_api.writeClusterManifest(alloc, backup_root_abs, &cluster_manifest);
    try publishTestCommittedClusterAttempt(
        alloc,
        backup_root_abs,
        "attempt-extension-restore",
        "snap-cluster",
        "docs",
        "docs-snap-cluster",
        .portable,
    );

    const State = struct {
        table_restored: bool = false,
        installed_count: usize = 0,
        member_count: usize = 0,
        dependency_count: usize = 0,
        tables: [1]metadata_table_manager.TableRecord = .{.{
            .table_id = 1,
            .name = "docs",
        }},
        ranges: [1]metadata_table_manager.RangeRecord = .{.{
            .group_id = 7001,
            .range_id = 7001,
            .table_id = 1,
            .start_key = "",
            .end_key = null,
        }},
        restore_progresses: [1]metadata_table_manager.RestoreProgressRecord,
    };

    const FakeSource = struct {
        state: *State,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .restore_table = restoreTable,
                    .restore_extensions = restoreExtensions,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = if (self.state.table_restored)
                    self.state.tables[0..]
                else
                    @constCast((&[_]metadata_table_manager.TableRecord{})[0..]),
                .ranges = if (self.state.table_restored)
                    self.state.ranges[0..]
                else
                    @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .restore_progresses = if (self.state.table_restored)
                    self.state.restore_progresses[0..]
                else
                    @constCast((&[_]metadata_table_manager.RestoreProgressRecord{})[0..]),
                .extension_packages = @constCast((&[_]extension_domain.PackageManifest{.{
                    .name = "memoryaf",
                    .version = "1.0.0",
                    .digest = "sha256:memory",
                    .install = .{ .scopes_supported = &.{.table} },
                }})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn restoreTable(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            location_uri_arg: []const u8,
            connection: []const u8,
            artifact_backup_id: []const u8,
            manifest: *const backups_api.TableBackupManifest,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expect(location_uri_arg.len > 0);
            try std.testing.expectEqualStrings("test-backups", connection);
            try std.testing.expectEqualStrings("docs-snap-cluster", artifact_backup_id);
            try std.testing.expectEqualStrings("docs-snap-cluster", manifest.backup_id);
            try std.testing.expectEqualStrings("docs", manifest.table_name);
            self.state.ranges[0].completed_restore_fingerprint =
                metadata_table_manager.restoreCompletionFingerprint(
                    manifest.backup_id,
                    artifact_backup_id,
                    location_uri_arg,
                );
            self.state.table_restored = true;
        }

        fn restoreExtensions(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            restored_installed: []const extension_domain.InstalledExtension,
            restored_members: []const extension_domain.ExtensionMember,
            restored_dependencies: []const extension_domain.ExtensionDependency,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.state.installed_count = restored_installed.len;
            self.state.member_count = restored_members.len;
            self.state.dependency_count = restored_dependencies.len;
        }
    };

    var state = State{
        .restore_progresses = .{.{
            .table_id = 1,
            .node_id = 1,
            .group_id = 7001,
            .backup_id = "docs-snap-cluster",
            .artifact_backup_id = "docs-snap-cluster",
            .location = location_uri,
            .snapshot_path = "artifacts/groups/7001.afb",
            .artifact_sha256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
            .primary_restored = true,
            .runtime_repair_complete = true,
            .phase = "complete",
        }},
    };
    var source = FakeSource{ .state = &state };
    var node_config = try testBackupNodeConfig(alloc);
    defer node_config.deinit();
    var backend_runtime = try db_mod.background_runtime.BackendRuntime.init(alloc, .{});
    defer backend_runtime.deinit();
    var server = ApiHttpServer.init(alloc, .{ .node_config = &node_config, .backend_runtime = &backend_runtime }, source.iface(), null, null);
    defer server.deinit();
    try attachTestRestoreJobStore(alloc, &server, &tmp.sub_path, "restore-jobs");

    const restore_body = try std.fmt.allocPrint(
        alloc,
        "{{\"backup_id\":\"snap-cluster\",\"location\":\"{s}\",\"connection\":\"test-backups\"}}",
        .{location_uri},
    );
    defer alloc.free(restore_body);
    var restore_resp = try server.handle(.{
        .method = .POST,
        .uri = "/restore",
        .body = restore_body,
        .content_type = "application/json",
    });
    defer restore_resp.deinit(alloc);

    try std.testing.expectEqual(@as(u16, 202), restore_resp.status);
    const terminal_restore = try waitForTerminalRestoreJobAlloc(alloc, &server, restore_resp.body);
    defer alloc.free(terminal_restore);
    try std.testing.expect(state.table_restored);
    try std.testing.expectEqual(@as(usize, 1), state.installed_count);
    try std.testing.expectEqual(@as(usize, 1), state.member_count);
    try std.testing.expectEqual(@as(usize, 1), state.dependency_count);
}

test "api http server prefers metadata-owned restore over inline write-source restore" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const location_uri = try writeTestRestoreManifestLocationAlloc(alloc, &tmp.sub_path, "metadata-restore-backup", "snap1", "docs");
    defer alloc.free(location_uri);

    const RestoreSource = struct {
        restored: bool = false,
        expected_location: []const u8,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .restore_table = restoreTable,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn restoreTable(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            location_uri_arg: []const u8,
            connection: []const u8,
            artifact_backup_id: []const u8,
            manifest: *const backups_api.TableBackupManifest,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expectEqualStrings(self.expected_location, location_uri_arg);
            try std.testing.expectEqualStrings("test-backups", connection);
            try std.testing.expectEqualStrings("snap1", artifact_backup_id);
            try std.testing.expectEqualStrings("snap1", manifest.backup_id);
            try std.testing.expectEqualStrings("docs", manifest.table_name);
            self.restored = true;
        }
    };

    const FailingWrites = struct {
        fn source() table_writes.TableWriteSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .batch = unsupportedBatch,
                    .create_table = unsupportedCreateTable,
                    .update_schema = unsupportedUpdateSchema,
                    .create_index = unsupportedCreateIndex,
                    .drop_index = unsupportedDropIndex,
                    .backup_table = unsupportedBackupTable,
                    .restore_table = restoreTable,
                    .commit_transaction = unsupportedCommitTransaction,
                    .commit_transaction_with_id = unsupportedCommitTransactionWithId,
                    .batch_group_local = unsupportedBatchGroupLocal,
                    .txn_begin_group_local = unsupportedTxnBeginGroupLocal,
                    .txn_prepare_group_local = unsupportedTxnPrepareGroupLocal,
                    .txn_resolve_group_local = unsupportedTxnResolveGroupLocal,
                },
            };
        }

        fn restoreTable(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: backups_api.TableRestorePlan) anyerror!?void {
            return error.TestUnexpectedResult;
        }

        fn unsupportedBatch(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.BatchRequest) anyerror!?void {
            return error.UnsupportedOperation;
        }
        fn unsupportedCreateTable(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: tables_api.CreateTableRequest) anyerror!?void {
            return error.UnsupportedOperation;
        }
        fn unsupportedUpdateSchema(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8) anyerror!?void {
            return error.UnsupportedOperation;
        }
        fn unsupportedCreateIndex(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8) anyerror!?void {
            return error.UnsupportedOperation;
        }
