        \\  {{"_id":"doc:1","_source":{{"customer_id":"{s}"}}}},
        \\  {{"_id":"doc:2","_source":{{"customer_id":"{s}"}}}}
        \\]
    , .{ partition_zero_key, partition_one_key });
    defer std.testing.allocator.free(hits_body);
