            owned_hits[0] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"_id\":\"doc:1\",\"_source\":{\"customer_id\":\"cust:a\",\"customers.name\":\"Alice\"}}");
            var completed: ApiHttpServer.JoinPartitionExecutionResult = .{
